'use strict';
window.HECReelControls=(()=>{
 const defaults={shortcutDesign:'شفاف بإطار لامع',shortcutPalette:'أسود وذهبي',shortcutOpacity:16,shortcutMovable:true,shortcutShine:true,enableShare:true,enableLikes:true,enableComments:true,enableCart:true};
 const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const paths={like:'M20.8 4.6a5.4 5.4 0 0 0-7.6 0L12 5.8l-1.2-1.2a5.4 5.4 0 0 0-7.6 7.6L12 21l8.8-8.8a5.4 5.4 0 0 0 0-7.6Z',comment:'M21 11a9 9 0 0 1-9 9H4l-3 3V11a10 10 0 0 1 20 0Z',share:'m8 11 8-5M8 13l8 5M8 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0ZM22 4a3 3 0 1 1-6 0 3 3 0 0 1 6 0ZM22 20a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',cart:'M1 2h3l3 13h12l3-9H5M10 21a1 1 0 1 1-2 0 1 1 0 0 1 2 0ZM19 21a1 1 0 1 1-2 0 1 1 0 0 1 2 0Z'};
 const icon=k=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[k]}" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round" stroke-linecap="round"/></svg>`;
 const ui=()=>window.HECERP?.ui(),say=(t,tone)=>window.HECFeedback?HECFeedback.show(t,{tone}):ui()?.toast(t),products=r=>(r.productIds||[]).map(id=>HEC.products.find(p=>p.id===id&&!p.hidden)).filter(Boolean);
 let active=null,cfg={...defaults},panel=null,trigger=null,pending=new Map(),stats=new Map(),last=new Map(),suppress=0;
 const positionKey='hec.reels.shortcut.position.v1';
 const sizeKey='hec.reels.size.v1';
 const dimensions={shortcutWidth:['عرض الاختصار',44,96,48],shortcutHeight:['ارتفاع الاختصار',76,240,98],trayWidth:['عرض لوحة الفيديوهات',240,640,430],trayHeight:['ارتفاع لوحة الفيديوهات',168,440,208]};
 const clamp=(n,min,max)=>Math.max(min,Math.min(max,n));
 function sanitizeSizes(raw){const next={};if(raw&&typeof raw==='object'&&!Array.isArray(raw))for(const [k,[,min,max]] of Object.entries(dimensions))if(Number.isFinite(raw[k]))next[k]=clamp(Math.round(raw[k]),min,max);return next}
 function readSizes(){try{return sanitizeSizes(JSON.parse(localStorage.getItem(sizeKey)||'{}'))}catch{return {}}}
 function shortcut(el,c){
  const palettes={'أسود وذهبي':['#151217','#b79340','#ffe9a6'],'هوية المتجر':['#181216','#72223f','#d9b561'],'زمردي وذهبي':['#093f33','#be9e52','#eee0ab'],'كحلي وفضي':['#152940','#90a9c1','#e4eef9'],'عنابي وذهبي':['#48182c','#bf9b50','#f7e0a2']},colors=palettes[c.shortcutPalette]||palettes[defaults.shortcutPalette];
  colors.forEach((v,i)=>el.style.setProperty('--reels-tone-'+i,v));el.style.setProperty('--reels-opacity',String(clamp(Number(c.shortcutOpacity)||0,0,85)/100));el.classList.toggle('reels-gloss',c.shortcutShine!==false);
  el.dataset.shortcutDesign=c.shortcutDesign==='الشريط الأحمر الكلاسيكي'?'classic':'glass';
  let sizes=readSizes(),saved=null;try{const raw=JSON.parse(localStorage.getItem(positionKey)||'null');if(Number.isFinite(raw?.x)&&Number.isFinite(raw?.y))saved={x:clamp(raw.x,0,1),y:clamp(raw.y,0,1)}}catch{}
  const button=el.querySelector('.reels-toggle'),tray=el.querySelector('.reels-quick');
  button.title=c.shortcutMovable===false?'فتح أحدث الريلز':'انقر للفتح؛ اسحب لتغيير المكان. لتغيير العرض والارتفاع افتح «الحجم».';button.classList.toggle('movable',c.shortcutMovable!==false);
  const settings=document.createElement('button');settings.className='reels-size-button';settings.textContent='الحجم';settings.setAttribute('aria-label','تغيير حجم اختصار الريلز ولوحة الفيديوهات');settings.onclick=e=>{e.stopPropagation();sizeSheet(el,c)};tray.querySelector('header').append(settings);
  const closer=document.createElement('button');closer.dataset.reel='collapse';closer.className='reels-tray-close';closer.textContent='×';closer.setAttribute('aria-label','إغلاق أحدث الريلز');tray.querySelector('header').append(closer);
  function bounds(){const v=window.visualViewport,left=v?.offsetLeft||0,top=v?.offsetTop||0,w=v?.width||innerWidth,h=v?.height||innerHeight;const edge=Math.max(0,(w-760)/2);return {left:left+edge+8,right:left+w-edge-8,top:top+8,bottom:top+h-8,w:w-edge*2-16,h:h-16}}
  function layout(x,y,remember=false){const b=bounds(),width=clamp(sizes.shortcutWidth||48,44,Math.max(44,b.w)),height=clamp(sizes.shortcutHeight||(el.dataset.shortcutDesign==='classic'?180:98),44,Math.max(44,b.h));el.style.setProperty('--shortcut-width',width+'px');el.style.setProperty('--shortcut-height',height+'px');
   x=clamp(x,b.left,Math.max(b.left,b.right-width));y=clamp(y,b.top,Math.max(b.top,b.bottom-height));el.style.left=x+'px';el.style.top=y+'px';el.classList.toggle('open-left',x>(b.left+b.right)/2);
   const requestedW=sizes.trayWidth||430,requestedH=sizes.trayHeight||208,tw=Math.min(requestedW,b.w),th=Math.min(requestedH,b.h),spaceRight=b.right-x-width-8,spaceLeft=x-b.left-8;let tx,ty;
   if(Math.max(spaceRight,spaceLeft)>=tw){tx=spaceRight>=tw?x+width+8:x-tw-8;ty=clamp(y,b.top,b.bottom-th)}
   else{tx=clamp(x,b.left,b.right-tw);const below=b.bottom-y-height-8,above=y-b.top-8;ty=below>=th?y+height+8:above>=th?y-th-8:clamp(y,b.top,b.bottom-th)}
   tray.style.setProperty('--tray-width',tw+'px');tray.style.setProperty('--tray-height',th+'px');tray.style.setProperty('--tray-left',(tx-x)+'px');tray.style.setProperty('--tray-top',(ty-y)+'px');
   if(remember){const next={x:(x-b.left)/Math.max(1,b.w-width),y:(y-b.top)/Math.max(1,b.h-height)};try{localStorage.setItem(positionKey,JSON.stringify(next));saved=next;say('تم حفظ مكان اختصار الريلز','success')}catch{say('تعذر حفظ المكان؛ تحقق من مساحة الجهاز','error')}}
  }
  function restore(){const b=bounds(),width=sizes.shortcutWidth||48,height=sizes.shortcutHeight||(el.dataset.shortcutDesign==='classic'?180:98);layout(saved?b.left+saved.x*Math.max(0,b.w-width):b.left,saved?b.top+saved.y*Math.max(0,b.h-height):b.top+b.h*.35)}
  el.reelsSizing={apply(value){sizes=sanitizeSizes(value);restore()},current:()=>({...sizes})};restore();
  let start=null,moved=false;
  button.addEventListener('pointerdown',e=>{if(c.shortcutMovable===false||e.button!==0)return;start={x:e.clientX,y:e.clientY,left:parseFloat(el.style.left),top:parseFloat(el.style.top),id:e.pointerId};moved=false;button.setPointerCapture(e.pointerId)});
  button.addEventListener('pointermove',e=>{if(!start||e.pointerId!==start.id)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;if(Math.hypot(dx,dy)>7)moved=true;if(moved){e.preventDefault();layout(start.left+dx,start.top+dy)}});
  function finish(e,cancel=false){if(!start)return;if(moved){suppress=Date.now()+500;if(cancel)restore();else layout(parseFloat(el.style.left),parseFloat(el.style.top),true)}start=null;if(button.hasPointerCapture(e.pointerId))button.releasePointerCapture(e.pointerId)}
  button.addEventListener('pointerup',e=>finish(e));button.addEventListener('pointercancel',e=>finish(e,true));button.addEventListener('lostpointercapture',e=>finish(e,true));
  button.addEventListener('keydown',e=>{if(c.shortcutMovable===false||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home'].includes(e.key))return;e.preventDefault();e.stopPropagation();if(e.key==='Home'){try{localStorage.removeItem(positionKey);saved=null;restore();say('عاد الاختصار إلى مكانه الافتراضي','success')}catch{say('تعذر حفظ المكان','error')}}else layout(parseFloat(el.style.left)+({ArrowLeft:-20,ArrowRight:20}[e.key]||0),parseFloat(el.style.top)+({ArrowUp:-20,ArrowDown:20}[e.key]||0),true)});
  const cleanup=()=>{removeEventListener('resize',resize);window.visualViewport?.removeEventListener('resize',resize);window.visualViewport?.removeEventListener('scroll',resize);removeEventListener('storage',storage);observer.disconnect()};
  const resize=()=>{if(!el.isConnected){cleanup();return}restore()},storage=e=>{if(e.key===sizeKey){sizes=readSizes();restore()}};
  addEventListener('resize',resize);window.visualViewport?.addEventListener('resize',resize);window.visualViewport?.addEventListener('scroll',resize);addEventListener('storage',storage);
  const observer=new MutationObserver(()=>{if(!el.isConnected)cleanup()});observer.observe(el.parentNode,{childList:true});
 }
 function sizeSheet(el,c){const original=el.reelsSizing.current();let draft={...original},committed=false;
  const value=k=>draft[k]||(k==='shortcutHeight'&&c.shortcutDesign==='الشريط الأحمر الكلاسيكي'?180:dimensions[k][3]);
  const p=sheet('حجم الريلز على جهازك',`<p>اضبط المقاس المناسب لك. يصغر الإطار تلقائياً عندما تكون الشاشة أصغر.</p><form class="reels-size-form"><div class="reels-size-presets"><button type="button" data-size-preset="small">صغير</button><button type="button" data-size-preset="medium">متوسط</button><button type="button" data-size-preset="large">كبير</button></div>${Object.entries(dimensions).map(([k,[label,min,max]])=>`<label for="reels-size-${k}">${E(label)}<output for="reels-size-${k}" data-size-value="${k}">${value(k)} بكسل</output></label><input type="range" id="reels-size-${k}" name="${k}" min="${min}" max="${max}" step="1" value="${value(k)}">`).join('')}<button type="button" class="reels-size-reset">المقاس التلقائي</button><button type="submit" class="social-primary">حفظ الحجم على جهازي</button></form>`);
  p.classList.add('reels-size-sheet');p.onDismiss=()=>{if(!committed)document.getElementById('reels-shortcut')?.reelsSizing?.apply(original)};
  function update(){for(const k of Object.keys(dimensions)){p.querySelector(`[name="${k}"]`).value=value(k);p.querySelector(`[data-size-value="${k}"]`).textContent=value(k)+' بكسل'}document.getElementById('reels-shortcut')?.reelsSizing?.apply(draft)}
  p.querySelector('form').oninput=e=>{if(!(e.target.name in dimensions))return;draft[e.target.name]=Number(e.target.value);update()};
  p.querySelectorAll('[data-size-preset]').forEach(b=>b.onclick=()=>{const preset={small:[44,84,280,184],medium:[56,128,400,240],large:[72,192,600,360]}[b.dataset.sizePreset];draft=Object.fromEntries(Object.keys(dimensions).map((k,i)=>[k,preset[i]]));update();say('معاينة المقاس؛ اضغط حفظ للاحتفاظ به','info')});
  p.querySelector('.reels-size-reset').onclick=()=>{draft={};update();say('تمت معاينة المقاس التلقائي؛ احفظ لتطبيقه','info')};
  p.querySelector('form').onsubmit=e=>{e.preventDefault();try{localStorage.setItem(sizeKey,JSON.stringify(sanitizeSizes(draft)));committed=true;closePanel();say('تم حفظ حجم الريلز على جهازك','success')}catch{error(p,{message:'تعذر حفظ الحجم. بقيت الإعدادات السابقة محفوظة؛ أفرغ مساحة ثم حاول مجدداً.'})}};
 }
 window.addEventListener('click',e=>{if(Date.now()<suppress&&e.target.closest('#reels-shortcut')){e.preventDefault();e.stopImmediatePropagation()}},true);
 function toolbar(r,c){const items=[['like','إعجاب','enableLikes'],['comment','تعليق','enableComments'],['share','مشاركة','enableShare'],['cart','إلى السلة','enableCart']];return `<aside class="reel-social" data-social-id="${E(r.id)}" aria-label="التفاعل مع الفيديو">${items.filter(([k,,f])=>c[f]!==false&&(k!=='cart'||products(r).length)).map(([k,t])=>`<button data-reel-social="${k}" aria-label="${t}" ${k==='like'?'aria-pressed="false"':''}>${icon(k)}<small>${t}</small>${['like','comment'].includes(k)?'<span class="social-count"></span>':k==='cart'?'<span class="reel-cart-total"></span>':''}</button>`).join('')}<p class="reel-social-status" role="status"></p></aside>`}
 function draw(id,result){stats.set(id,result);document.querySelectorAll('.reel-social').forEach(el=>{if(el.dataset.socialId!==id)return;const like=el.querySelector('[data-reel-social=like]');like?.setAttribute('aria-pressed',String(result.liked));if(like)like.querySelector('.social-count').textContent=String(result.likes);const comment=el.querySelector('[data-reel-social=comment] .social-count');if(comment)comment.textContent=String(result.commentCount)})}
 async function load(r,manager=false){const result=await HECERP.call(manager?'admin.reels.comments':'reels.social',{reel_id:r.id});if(!manager)draw(r.id,result);return result}
 function activate(r,c){cfg={...defaults,...c};if(!r)return;if(active?.id!==r.id)closePanel();active=r;if(stats.has(r.id))draw(r.id,stats.get(r.id));if(pending.has(r.id)||Date.now()-(last.get(r.id)||0)<10000)return;last.set(r.id,Date.now());const promise=load(r).catch(e=>{document.querySelectorAll('.reel-social').forEach(el=>{if(el.dataset.socialId===r.id)el.querySelector('.reel-social-status').textContent=HECERP.available()?'تعذر تحديث التفاعل':'الإعجاب والتعليقات يتطلبان اتصال المتجر'})}).finally(()=>pending.delete(r.id));pending.set(r.id,promise)}
 function closePanel(){panel?.onDismiss?.();panel?.remove();panel=null;trigger?.focus({preventScroll:true});trigger=null}
 function sheet(title,content){closePanel();trigger=document.activeElement;document.querySelectorAll('#reels-viewer video').forEach(v=>{v.pause();v.closest('.reel-page').classList.remove('playing')});panel=document.createElement('section');panel.className='reel-sheet';panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-label',title);panel.innerHTML=`<header><h2>${E(title)}</h2><button data-social-close aria-label="إغلاق">×</button></header><div class="reel-sheet-body">${content}</div><p class="social-error" role="alert"></p>`;(document.getElementById('reels-viewer')||document.body).append(panel);panel.querySelector('[data-social-close]').onclick=closePanel;panel.querySelector('textarea,input,select,button')?.focus({preventScroll:true});return panel}
 function error(p,e){const message=e.message||'تعذر الاتصال. حاول مرة أخرى.';if(p?.isConnected)p.querySelector('.social-error').textContent=message;say(message,'error')}
 async function share(r){const native=/HECAndroid\//.test(navigator.userAgent)&&location.hostname==='appassets.androidplatform.net';if(native){const a=document.createElement('a');a.href='https://appassets.androidplatform.net/native-reel-share#'+encodeURIComponent(r.id);a.hidden=true;document.body.append(a);a.click();a.remove();return;}const url=new URL('/customer/index.html',location.origin);url.hash='reels/'+r.id;const data={title:r.title,text:'شاهد '+r.title+' في متجر الهيثم',url:url.href};if(navigator.share){try{await navigator.share(data);say('اكتملت عملية المشاركة على جهازك','success');return}catch(e){if(e.name==='AbortError'){say('أُلغيت المشاركة','info');return}}}const p=sheet('مشاركة الريلز',`<p>انسخ الرابط وشاركه في واتساب أو أي تطبيق.</p><textarea readonly dir="ltr" aria-label="رابط الفيديو">${E(data.url)}</textarea><button class="social-primary" data-copy-reel>نسخ الرابط</button>`);p.querySelector('[data-copy-reel]').onclick=async()=>{try{await navigator.clipboard.writeText(data.url);say('تم نسخ رابط الفيديو')}catch{p.querySelector('textarea').select();error(p,{message:'اضغط مطولاً على الرابط ثم اختر نسخ.'})}}}
 async function like(r,b){b.disabled=true;try{const current=await load(r);const result=await HECERP.call('reels.react',{reel_id:r.id,liked:!current.liked});draw(r.id,result);const product=products(r)[0];if(product)ui()?.reelFavourite(product.id,result.liked);say(result.liked?(product?'تم الإعجاب وحفظ الصنف في المفضلة':'تم الإعجاب بالفيديو'):'تم إلغاء الإعجاب')}catch(e){say(e.message)}finally{b.disabled=false}}
 function add(p,variant){const total=ui()?.reelCart(p.id,variant);if(total===undefined)throw Error('تعذر الوصول إلى السلة');document.querySelectorAll('.reel-cart-total').forEach(el=>el.textContent=total+' في السلة');window.HECFeedback?HECFeedback.show('أضيف '+p.name+' إلى السلة',{tone:'success',action:{label:'فتح السلة',run:()=>ui()?.go('cart')}}):say('أضيف '+p.name+' إلى السلة');return total}
 function cart(r){const list=products(r);if(!list.length){say('لا توجد أصناف متاحة لهذا الفيديو');return}if(list.length===1&&!list[0].variants?.length){try{add(list[0]);}catch(e){say(e.message)}return}const p=sheet('إضافة إلى السلة',list.map((item,i)=>`<article class="social-cart-item"><b>${E(item.name)}</b><p>${E(HEC.money(item.price))}</p>${item.variants?.length?`<select data-variant="${i}" aria-label="خيار ${E(item.name)}">${item.variants.map(v=>`<option value="${E(v.id)}">${E(v.label)} · ${E(HEC.money(v.price??item.price))}</option>`).join('')}</select>`:''}<button class="social-primary" data-add-item="${i}">إضافة إلى السلة</button></article>`).join(''));p.querySelectorAll('[data-add-item]').forEach(b=>b.onclick=()=>{try{const i=Number(b.dataset.addItem);add(list[i],p.querySelector(`[data-variant="${i}"]`)?.value);closePanel()}catch(e){error(p,e)}})}
 async function comments(r,manager=false){const p=sheet(manager?'إدارة تعليقات الفيديو':'التعليقات',`<div class="social-comments" aria-live="polite">جارٍ جلب التعليقات…</div>${manager?'':`<form class="social-comment-form"><label for="reel-comment-text">تعليقك</label><textarea id="reel-comment-text" name="text" maxlength="1000" required placeholder="اكتب تعليقاً…"></textarea><small>يظهر تعليقك للمستخدمين باسم حسابك. يمكنك حذفه لاحقاً.</small><button class="social-primary" type="submit">نشر التعليق</button></form>`}`);let request=null;
  function render(result){if(!p.isConnected)return;p.querySelector('.social-comments').innerHTML=`<p>${result.commentCount} تعليق${result.commentCount>50?' · أحدث 50':''}</p>`+(result.comments.map(c=>`<article class="social-comment"><header><b>${E(c.name)}</b><time>${E(new Date(c.createdAt).toLocaleDateString('ar'))}</time></header><p>${E(c.text)}</p>${c.canDelete?`<button data-comment-delete="${E(c.id)}">حذف</button>`:''}</article>`).join('')||'<p>لا توجد تعليقات بعد.</p>');if(!manager)draw(r.id,result);const form=p.querySelector('form');if(form){form.hidden=!result.commentsEnabled;if(!result.canInteract){form.hidden=true;p.querySelector('.social-comments').insertAdjacentHTML('beforeend','<p>سجّل الدخول بحساب العميل للمشاركة.</p><button data-comment-login class="social-primary">تسجيل الدخول</button>');p.querySelector('[data-comment-login]').onclick=()=>{closePanel();ui()?.go('erp-account')}}}p.querySelectorAll('[data-comment-delete]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{render(await HECERP.call(manager?'admin.reels.comment.delete':'reels.comment.delete',{reel_id:r.id,comment_id:b.dataset.commentDelete}));say('تم حذف التعليق','success')}catch(e){error(p,e);b.disabled=false}})}
  const form=p.querySelector('form');if(form)form.onsubmit=async e=>{e.preventDefault();const input=form.elements.text,text=input.value.trim();if(!text)return;if(!request||request.text!==text)request={text,id:crypto.randomUUID()};const button=form.querySelector('button');button.disabled=true;p.querySelector('.social-error').textContent='';try{const result=await HECERP.call('reels.comment',{reel_id:r.id,text,request_id:request.id});input.value='';request=null;render(result);say('تم نشر تعليقك','success')}catch(e){error(p,e)}finally{button.disabled=false}};
  try{render(await load(r,manager))}catch(e){p.querySelector('.social-comments').textContent='تعذر جلب التعليقات.';if(form)form.hidden=true;error(p,e)}
 }
 document.addEventListener('click',e=>{const b=e.target.closest('[data-reel-social]');if(b){e.preventDefault();e.stopPropagation();const id=b.closest('[data-social-id]').dataset.socialId,r=HECReels.rows().find(r=>r.id===id);if(!r)return;({like:()=>like(r,b),share:()=>share(r),comment:()=>comments(r),cart:()=>cart(r)})[b.dataset.reelSocial]?.()}const admin=e.target.closest('[data-reel-manage-comments]');if(admin){e.preventDefault();comments({id:admin.dataset.reelManageComments},true)}},true);
 window.addEventListener('keydown',e=>{if(!panel)return;if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();closePanel();return}if(['ArrowDown','ArrowUp','PageDown','PageUp'].includes(e.key))e.stopImmediatePropagation();if(e.key==='Tab'){const all=[...panel.querySelectorAll('button,a,textarea,input,select')].filter(el=>!el.disabled&&el.getClientRects().length);if(e.shiftKey&&document.activeElement===all[0]){e.preventDefault();all.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===all.at(-1)){e.preventDefault();all[0]?.focus()}e.stopImmediatePropagation()}},true);
 window.addEventListener('hashchange',()=>{closePanel();active=null;stats.clear();last.clear()});
 return {defaults,shortcut,toolbar,activate};
})();
